const PHRASES = { A: THEME_A, B: THEME_B, BRIDGE, REST, SOLO }

// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"A",0,1],[32,"A",0,1],[48,"A",0,1],[64,"A",0,1],[80,"A",0,1],[96,"A",0,1],[112,"REST",0,1],[176,"A",0,1],[192,"A",0,1],[208,"A",0,1],[224,"A",0,1],[240,"A",0,1],[256,"REST",0,1],[288,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"REST",0,1],[112,"B",0,1],[128,"B",0,1],[144,"B",0,1],[160,"B",0,1],[176,"REST",0,1],[192,"REST",0,1],[256,"BRIDGE",0,1],[272,"BRIDGE",0,1],[288,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[112,"REST",0,1],[176,"REST",0,1],[192,"HARMONY",0,1],[256,"REST",0,1],[288,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- cowbell -----------------------------------------------------------------------------------
const track0 = {
  color: '#ffffff',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["Cb = \\Rev\\,\\Dly\\Big[\\HP_{250}\\tanh\\!\\big(2.4\\,C(f, t)\\big)\\Big],\\quad C = \\big(0.62e^{-t/12\\text{мс}} + 0.38e^{-t/0.32}\\big)\\sum_{k\\ \\text{нечёт}}\\Big(\\tfrac{H(kf)}{k}\\sin 2\\pi kft + \\tfrac{0.85H(1.48kf)}{k}\\sin 2\\pi\\,1.48kft\\Big)","H(\\nu) = \\Big(1 + 1.3^2\\big(\\tfrac{\\nu}{4.9f} - \\tfrac{4.9f}{\\nu}\\big)^2\\Big)^{-1/2}\\ \\text{— полоса 808 (2.64 кГц над 540 Гц)}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(cowbellTone, { release: 0.05, life: 1.4, max: 8 }), fire = trigger(), hp = filter('hp'), echo = delay({ time: sec * 0.75, feedback: 0.3, wet: 0.22 }), verb = reverb({ room: 0.82, damp: 0.4, wet: 0.28 })
    return x => {
      const m = leadAt(x)
      if (fire(m ? m.at : null)) p.hit(hz(m.n, C4), 0.85 + 0.15 * hash(floor(4 * x), 9), 1.2)
      return verb(...echo(...pan(0.896 * hp(tanh(2.4 * p()), 250), 0.12)))
    }
  },
}

